0,"prerequisites":["129e7446-e579-576a-9cce-c4e324ef708f"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"0c184e75-e4af-5511-b8f8-5d92ec0403b5","unit_id":"59a38e16-f2a7-562b-994b-0955bf8f6c28","title":"Гипотезы и упущенные возможности","position":1,"description":"Различаем нереальное настоящее и альтернативное прошлое, не смешивая временные значения.","level":"B2","objectives":["Строить second и third conditional","Объяснять последствия несостоявшегося решения"],"notes":["If I had more time, I would travel — гипотеза о настоящем.","If I had known, I would have called — альтернативное прошлое; had known не утверждает, что человек знал."],"lexicon":[{"en":"otherwise","ru":"иначе"},{"en":"regret","ru":"сожалеть"},{"en":"opportunity","ru":"возможность"},{"en":"outcome","ru":"исход, результат"}],"skills":["grammar","reading","vocabulary"],"estimated_minutes":10,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"f3d5e543-c83d-5ae9-a85c-d320eb8c55b1","unit_id":"59a38e16-f2a7-562b-994b-0955bf8f6c28","title":"Сообщения и осторожные выводы","position":2,"description":"Передаём чужие сообщения и отличаем подтверждённый факт от сообщения о нём.","level":"B2","objectives":["Использовать reporting passive","Сохранять источник и степень уверенности"],"notes":["The company is said to … передаёт распространённое сообщение, а не личное подтверждение автора.","В пересказе из прошлого reported speech может требовать сдвига времени, если ситуация относится к тому прошлому контексту."],"lexicon":[{"en":"reportedly","ru":"по сообщениям"},{"en":"claim","ru":"утверждать"},{"en":"deny","ru":"отрицать"},{"en":"evidence","ru":"доказательства, данные"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":10,"prerequisites":["0c184e75-e4af-5511-b8f8-5d92ec0403b5"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"cbd16cfa-daf2-5b00-a00f-73ae3d170d55","unit_id":"59a38e16-f2a7-562b-994b-0955bf8f6c28","title":"Аргументы без крайностей","position":3,"description":"Строим сбалансированное рассуждение, различаем аргумент и чрезмерное обобщение.","level":"B2","objectives":["Использовать although, despite и however","Выделять ограниченный, обоснованный вывод"],"notes":["Despite требует существительного или -ing; although вводит придаточное с подлежащим и сказуемым.","However связывает противопоставленные идеи; одно преимущество не доказывает отсутствие недостатков."],"lexicon":[{"en":"drawback","ru":"недостаток"},{"en":"nevertheless","ru":"тем не менее"},{"en":"flexibility","ru":"гибкость"},{"en":"trade-off","ru":"компромисс, баланс потерь и выгод"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":10,"prerequisites":["f3d5e543-c83d-5ae9-a85c-d320eb8c55b1"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"ec5a99eb-159c-5c3a-9ec9-ea412352e7c5","unit_id":"59a38e16-f2a7-562b-994b-0955bf8f6c28","title":"Что могло произойти","position":4,"description":"Различаем вывод, возможность и невозможность при обсуждении прошлого.","level":"B2","objectives":["Использовать must/might/can’t have + причастие","Не выдавать предположение за доказанный факт"],"notes":["Must have — сильный вывод о прошлом на основании признаков, а не обязательство.","Might have — возможность; can’t have — вывод о невозможности."],"lexicon":[{"en":"deduce","ru":"делать вывод"},{"en":"apparently","ru":"по-видимому"},{"en":"unlikely","ru":"маловероятный"},{"en":"assumption","ru":"предположение"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":10,"prerequisites":["cbd16cfa-daf2-5b00-a00f-73ae3d