,"skills":["vocabulary","grammar","reading"],"estimated_minutes":12,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"b6f7588f-b44e-5845-8b1a-a786d911e8d5","unit_id":"5d4e5499-ce40-5871-833f-a03416dc68f1","title":"Номинализация без перегруза","position":2,"description":"Читаем формальную прозу и выбираем между ясной глагольной конструкцией и уместной номинализацией.","level":"C1","objectives":["Распознавать действия, скрытые в существительных","Сохранять субъект и причинность при редактуре"],"notes":["A reduction in costs может передавать costs were reduced, но сам по себе не называет исполнителя.","Номинализация не всегда улучшает стиль: цепочка абстрактных существительных может скрыть действие."],"lexicon":[{"en":"implementation","ru":"внедрение"},{"en":"reduction","ru":"снижение"},{"en":"accountability","ru":"подотчётность"},{"en":"attribution","ru":"приписывание, установление авторства или причины"}],"skills":["vocabulary","reading","grammar"],"estimated_minutes":12,"prerequisites":["0303140c-00c8-53b6-b2ad-5a4ce6c8a747"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"f072de5a-e807-5a58-a715-dbcf97b37659","unit_id":"5d4e5499-ce40-5871-833f-a03416dc68f1","title":"Осторожность научного вывода","position":3,"description":"Соразмеряем силу утверждения данным и не подменяем ограниченный результат универсальным правилом.","level":"C1","objectives":["Использовать hedging для ограниченных данных","Различать may suggest и conclusively proves"],"notes":["May suggest указывает на возможный вывод; conclusively proves заявляет гораздо большую силу доказательства.","Оговорка о выборке меняет область применимости вывода и не равна признанию полной бесполезности исследования."],"lexicon":[{"en":"tentative","ru":"предварительный, осторожный"},{"en":"sample","ru":"выборка"},{"en":"generalisable","ru":"пригодный для обобщения"},{"en":"limitation","ru":"ограничение"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["b6f7588f-b44e-5845-8b1a-a786d911e8d5"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"d7d86ac8-bfd7-5760-979f-dd08aa72b0de","unit_id":"5d4e5499-ce40-5871-833f-a03416dc68f1","title":"Оценка предложения и источников","position":4,"description":"Сравниваем убедительность профессиональных аргументов и отделяем свидетельство от рекламного обещания.","level":"C1","objectives":["Различать независимое подтверждение и заинтересованное заявление","Уточнять критерии сравнения"],"notes":["A testimonial — отзыв; он не равен независимому сравнительному исследованию.","Like-for-like comparison требует сравнивать сопоставимые условия, а не только красивые итоговые числа."],"lexicon":[{"en":"testimonial","ru":"отзыв, свидетельство клиента"},{"en":"independent","ru":"независимый"},{"en":"benchmark","ru":"ориентир для сравнения"},{"en":"corroborate","ru":"подтверждать дополнительными данными"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["f072de5a-e807-5a58-a715-dbcf97b37659"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"836a38b3-271d-51e7-b452-17062cee67d4","unit_id":"5d4e5499-ce40-5871-833f-a03416dc68f1","title":"Уступка без потери позиции","position":5,"description":"Строим аргумент, который признаёт ограничение, но сохраняет основную обоснованную позицию.","level":"C1","objectives":["Различать уступку, условие и контраст","Использовать even if, whereas и nonetheless"],"notes":["Even if вводит условие, которое не меняет главный вывод; оно не подтверждает, что условие выполнено.","Whereas сопоставляет разные положения дел; nonetheless сохраняет вывод вопреки названному ограничению."],"lexicon":[{"en":"nonetheless","ru":"тем не менее"},{"en":"whereas","ru":"тогда как"},{"en":"concede","ru":"признавать довод или уступать"},{"en":"feasibility","ru":"осуществимость"}],"skills":["vocabulary","reading","grammar"],"estimated_minutes":12,"prerequisites":["d7d86ac8-bfd7-5760-979f-dd08aa72b0de"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"91628438-0914-524a-ae2c-77665a7f5aa6","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Похвала, ирония и недосказанность","position":1,"description":"Различаем буквальную похвалу, ироническую оценку и ограниченный вывод из контекста.","level":"C2","objectives":["Интерпретировать ироническую похвалу по контексту","Сохранять сдержанную критику в переводе"],"notes":["Ироническая оценка определяется контекстом, а не самим наличием положительного прилагательного.","An ambitious interpretation может вежливо намекать на чрезмерность вывода, но не всегда является насмешкой."],"lexicon":[{"en":"understatement","ru":"сдержанное преуменьшение"},{"en":"ironic","ru":"иронический"},{"en":"qualified praise","ru":"похвала с оговорками"},{"en":"overstatement","ru":"преувеличение"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"38338103-b846-50c5-9c9d-2bc97e9f0d26","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Точность при смене регистра","position":2,"description":"Передаём сложное формальное условие простым языком, не уничтожая его оговорки.","level":"C2","objectives":["Сохранять исключения и модальную силу формулировки","Отличать понятность текста от изменения обязательства"],"notes":["May выражает разрешение или возможность, shall в формальном условии может задавать обязанность.","Переписывая текст простыми словами, нельзя молча убирать unless, subject to или временное ограничение."],"lexicon":[{"en":"subject to","ru":"при условии, с учётом"},{"en":"waiver","ru":"отказ от права или требования"},{"en":"provision","ru":"положение документа"},{"en":"plain language","ru":"понятный, незатруднённый язык"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["91628438-0914-524a-ae2c-77665a7f5aa6"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"0f2bab4d-9b53-57ca-8b86-f45ec49eb9d1","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Уступка и пределы контраргумента","position":3,"description":"Разбираем многоступенчатое рассуждение, в котором признание слабости не равносильно отказу от тезиса.","level":"C2","objectives":["Проследить область действия уступки","Не выводить из условного допущения утверждение о факте"],"notes":["For all its limitations = despite its limitations; оборот признаёт ограничение, но не задаёт итоговую оценку сам по себе.","Even were … to … может вводить формальное гипотетическое допущение, не подтверждая его реальность."],"lexicon":[{"en":"concede","ru":"признавать довод"},{"en":"undermine","ru":"подрывать"},{"en":"contingent","ru":"зависящий от обстоятельств"},{"en":"decisive","ru":"решающий"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["38338103-b846-50c5-9c9d-2bc97e9f0d26"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"12f5e759-0d8e-5f0a-b562-11d83627b1ac","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Метафора и рамка аргумента","position":4,"description":"Читаем редакционный текст, различаем образную формулировку и конкретное основание критики.","level":"C2","objectives":["Интерпретировать метафору через описанную ситуацию","Различать смену критерия и нормальное уточнение"],"notes":["Move the goalposts означает менять критерии так, что достижение цели становится менее доступным.","Метафора сама по себе не доказывает мотив; нужно смотреть, какую последовательность действий описывает автор."],"lexicon":[{"en":"move the goalposts","ru":"менять критерии достижения цели"},{"en":"yardstick","ru":"мерило, критерий оценки"},{"en":"pretext","ru":"предлог, отговорка"},{"en":"rationale","ru":"обоснование"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["0f2bab4d-9b53-57ca-8b86-f45ec49eb9d1"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"18df9422-22c8-5cc5-ad3d-915b70fa0d15","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Лексическая точность и границы вывода","position":5,"description":"Выбираем точное слово по его функции в сложном тексте и сохраняем различия близких понятий.","level":"C2","objectives":["Различать impartiality и отсутствие интереса","Сохранять разницу между отсутствием доказательства и доказательством отсутствия"],"notes":["В формальном контексте disinterested часто означает беспристрастный; uninterested — не проявляющий интереса. Контекст нужен, потому что употребление варьируется.","Failure to establish an effect не означает автоматически установление отсутствия эффекта."],"lexicon":[{"en":"disinterested","ru":"беспристрастный (в данном формальном контексте)"},{"en":"uninterested","ru":"не заинтересованный"},{"en":"inadvertent","ru":"непреднамеренный"},{"en":"inconclusive","ru":"не позволяющий сделать определённый вывод"}],"skills":["reading","vocabulary","grammar"],"estimated_minutes":12,"prerequisites":["12f5e759-0d8e-5f0a-b562-11d83627b1ac"],"quality":{"status":"checked","method":"author-review + schema/grader/edito