d":30},{"id":"4f65b9a1-5c81-5efa-bfda-dcc65521e742","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Как добраться на работу","position":12,"description":"Говорим о привычном способе передвижения и различаем by bus и on foot.","level":"A1","objectives":["Описать поездку с by","Использовать on foot для ходьбы"],"notes":["By bus/train/car — на автобусе/поезде/машине, без артикля.","On foot означает пешком; by foot в этом учебном контексте не используется."],"lexicon":[{"en":"bus stop","ru":"автобусная остановка"},{"en":"on foot","ru":"пешком"},{"en":"by train","ru":"на поезде"},{"en":"journey","ru":"поездка"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"e0eeda60-64e6-527d-9289-9f3396ed8ff7","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Считаем предметы","position":13,"description":"Задаём вопросы о количестве считаемых предметов и образуем простое множественное число.","level":"A1","objectives":["Использовать How many с множественным числом","Различить один предмет и несколько"],"notes":["How many используется с исчисляемым существительным во множественном числе.","Обычное множественное число получает -s, но child → children."],"lexicon":[{"en":"chair","ru":"стул"},{"en":"child","ru":"ребёнок"},{"en":"children","ru":"дети"},{"en":"shelf","ru":"полка"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"a2efeeaf-ef59-53bc-a749-26544cb77165","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Простые вежливые просьбы","position":14,"description":"Просим открыть окно, передать предмет или повторить фразу и реагируем на просьбу.","level":"A1","objectives":["Построить Can you …, please?","Согласиться выполнить просьбу"],"notes":["Can you open …? может быть просьбой, а не проверкой способности.","Please делает просьбу вежливее; после can глагол без to."],"lexicon":[{"en":"pass","ru":"передавать"},{"en":"repeat","ru":"повторять"},{"en":"window","ru":"окно"},{"en":"certainly","ru":"конечно"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"9b4ccf96-8296-5c13-ae84-7743f47ae4db","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Цена и оплата","position":15,"description":"Спрашиваем цену товара и понимаем простую сумму и способ оплаты.","level":"A1","objectives":["Спросить цену с How much","Попросить оплатить картой"],"notes":["How much is this …? спрашивает цену одного предмета.","Pay by card — платить картой; pay in cash — платить наличными."],"lexicon":[{"en":"price","ru":"цена"},{"en":"cash","ru":"наличные"},{"en":"card","ru":"карта"},{"en":"change","ru":"сдача"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"83d101e1-9a4b-5ed2-82f4-f33e6a142e75","unit_id":"c5316d46-d696-5c9d-b9a3-cd1b4c0a9485","title":"Привычки, которые изменились","position":1,"description":"Сравниваем прошлый и нынешний образ жизни с used to и Past Simple.","level":"B1","objectives":["Описать прежнее состояние с used to","Построить отрицание didn't use to"],"notes":["Used to описывает привычку или состояние, которые теперь изменились.","После didn't пишем use to без -d."],"lexicon":[{"en":"used to","ru":"раньше обычно"},{"en":"nowadays","ru":"в наши дни"},{"en":"commute","ru":"ездить на работу"},{"en":"move away","ru":"переехать в другое место"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"e03558f7-f5a2-5cee-b05c-1b3d6767053f","unit_id":"c5316d46-d696-5c9d-b9a3-cd1b4c0a9485","title":"Уточняем, о ком и о чём говорим","position":2,"description":"Опознаём людей, предметы и места с defining relative clauses без лишнего местоимения.","level":"B1","objectives":["Выбрать who, which и where по смыслу","Убрать повтор подлежащего в относительном предложении"],"notes":["Who связывает описание с человеком, which — с предметом; where обозначает место действия.","The woman who lives next door: после who не нужно повторять she."],"lexicon":[{"en":"neighbour","ru":"сосед"},{"en":"device","ru":"устройство"},{"en":"recommend","ru":"рекомендовать"},{"en":"identify","ru":"определять; опознавать"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"95830bb6-49ce-5426-90cf-af879054b2fb","unit_id":"c5316d46-d696-5c9d-b9a3-cd1b4c0a9485","title":"Как устроен процесс","position":3,"description":"Описываем производство и обслуживание в Present Simple Passive, когда исполнитель не важен.","level":"B1","objectives":["Построить is/are + past participle","Различить действие и объект процесса"],"notes":["Пассив строится be + причастие: The parcels are checked.","В описании процесса исполнитель часто не называется, если он очевиден."],"lexicon":[{"en":"sort","ru":"сортировать"},{"en":"deliver","ru":"доставлять"},{"en":"package","ru":"упаковывать"},{"en":"inspect","ru":"осматривать"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"28b596b1-fb0c-5b08-aa2c-309e0fc77921","unit_id":"c5316d46-d696-5c9d-b9a3-cd1b4c0a9485","title":"Уточняем вежливо","position":4,"description":"Используем косвенные вопросы в незнакомом месте и сохраняем прямой порядок слов.","level":"B1","objectives":["Построить Could you tell me …?","Использовать if в косвенном общем вопросе"],"notes":["В косвенной части порядок как в утверждении: where the station is.","После introductory phrase вопросительное do/does в косвенной части не нужно."],"lexicon":[{"en":"wonder","ru":"интересоваться; хотеть узнать"},{"en":"available","ru":"доступный; свободный"},{"en":"explain","ru":"объяснить"},{"en":"direct","ru":"прямой"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"1bb46fca-704b-5db1-a386-42f249e35c7a","unit_id":"c5316d46-d696-5c9d-b9a3-cd1b4c0a9485","title":"Планы, привычки и формы глагола","position":5,"description":"Различаем распространённые сочетания глаголов с -ing и to-infinitive без изменения смысла.","level":"B1","objectives":["Использовать enjoy/avoid + -ing","Использовать decide/hope + to-infinitive"],"notes":["После enjoy и avoid используется форма -ing.","После decide и hope используется to + начальная форма; это модель конкретного глагола."],"lexicon":[{"en":"avoid","ru":"избегать"},{"en":"decide","ru":"решить"},{"en":"hope","ru":"надеяться"},{"en":"suggest","ru":"предлагать"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"5b12e05e-6910-5f71-a4c9-952900195d3e","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Что произошло до прибытия","position":1,"description":"Что произошло до прибытия: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Показывать более раннее прошлое с had + причастие","Восстанавливать последовательность событий по рассказу"],"notes":["Past Perfect (had + причастие) показывает действие, завершившееся раньше другого момента в прошлом.","Past Simple продвигает рассказ; Past Perfect помогает объяснить уже существовавшую ситуацию."],"lexicon":[{"en":"platform","ru":"платформа"},{"en":"departure","ru":"отправление"},{"en":"announcement","ru":"объявление"},{"en":"miss","ru":"пропустить"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["1bb46fca-704b-5db1-a386-42f249e35c7a"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"f9036ed8-5811-5a28-83e1-c2dfcb07b8d8","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Как долго длится работа","position":2,"description":"Как долго длится работа: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Описывать продолжающийся процесс с have been + -ing","Различать начальную точку since и длительность for"],"notes":["Present Perfect Continuous: have/has been + -ing связывает начавшийся раньше процесс с настоящим.","For указывает длительность, since — начальную точку; вопрос How long часто относится к процессу."],"lexicon":[{"en":"rehearse","ru":"репетировать"},{"en":"performance","ru":"выступление"},{"en":"progress","ru":"прогресс"},{"en":"regularly","ru":"регулярно"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["5b12e05e-6910-5f71-a4c9-952900195d3e"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"99dadca9-2231-5598-af5c-6aa87bdd0807","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Договорённости на завтра","position":3,"description":"Договорённости на завтра: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Описывать подтверждённые договорённости через Present Continuous","Отличать исходное время встречи от согласованного переноса"],"notes":["Present Continuous с будущим временем может обозначать конкретную договорённость: I am meeting the tutor tomorrow.","Will часто используется для решения в момент речи; наличие подтверждённых времени и места помогает отличить договорённость."],"lexicon":[{"en":"appointment","ru":"назначенная встреча"},{"en":"confirm","ru":"подтвердить"},{"en":"reschedule","ru":"перенести встречу"},{"en":"available","ru":"свободный по времени"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["f9036ed8-5811-5a28-83e1-c2dfcb07b8d8"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"24bb7028-2dc2-5579-9086-1e410fcf2015","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Вежливые косвенные вопросы","position":4,"description":"Вежливые косвенные вопросы: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Сохранять прямой порядок слов в косвенном вопросе","Вежливо уточнять сведения через whether и вопросительные слова"],"notes":["Внутри косвенного вопроса используется прямой порядок слов: Could you tell me where the office is?","Do/does/did из прямого вопроса в такой части не сохраняются; для yes/no-вопроса подходят if или whether."],"lexicon":[{"en":"reception","ru":"стойка регистрации"},{"en":"office","ru":"кабинет"},{"en":"entrance","ru":"вход"},{"en":"directions","ru":"указания пути"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["99dadca9-2231-5598-af5c-6aa87bdd0807"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"49f1902c-6e6c-54df-9200-748b218c537d","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Оба варианта или ни один","position":5,"description":"Оба варианта или ни один: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Различать оба варианта и ни один из двух","Использовать both/neither of them и формальное согласование"],"notes":["Both относится к двум и означает «оба»; neither означает «ни один из двух».","Neither of + местоимение: neither of them. В этом уроке используем нейтральный формальный вариант neither of them is."],"lexicon":[{"en":"option","ru":"вариант"},{"en":"route","ru":"маршрут"},{"en":"direct","ru":"прямой"},{"en":"transfer","ru":"пересадка"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["24bb7028-2dc2-5579-9086-1e410fcf2015"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"0bfc327d-e509-51ba-ba8e-d75b34ca9fbe","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Передаём просьбу другому человеку","position":6,"description":"Передаём просьбу другому человеку: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Передавать просьбы через ask someone to do","Передавать отрицательные просьбы через not to"],"notes":["Передать просьбу можно через ask + человек + to-infinitive: She asked me to wait.","Для отрицательной просьбы используется not to: He asked us not to touch the screen."],"lexicon":[{"en":"request","ru":"просьба"},{"en":"remind","ru":"напомнить"},{"en":"equipment","ru":"оборудование"},{"en":"permission","ru":"разрешение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["49f1902c-6e6c-54df-9200-748b218c537d"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"e14d541f-1b76-58c2-b750-789cc15178f9","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Первое упоминание и знакомый предмет","position":7,"description":"Первое упоминание и знакомый предмет: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Выбирать артикль при первом и повторном упоминании","Различать a/an по начальному звуку, а не букве"],"notes":["A/an вводит один исчисляемый предмет впервые; the часто отсылает к уже известному предмету.","Выбор a/an зависит от звука: an umbrella, a useful tool; useful начинается со звука /j/."],"lexicon":[{"en":"umbrella","ru":"зонт"},{"en":"drawer","ru":"ящик"},{"en":"label","ru":"этикетка"},{"en":"useful","ru":"полезный"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["0bfc327d-e509-51ba-ba8e-d75b34ca9fbe"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"647fa429-7942-51bc-837d-6ff0dcb538b4","unit_id":"7830c0ec-43b4-5e94-b169-64d908059b9c","title":"Условие с unless","position":8,"description":"Условие с unless: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B1","objectives":["Выражать исключение из будущего плана через unless","Согласовывать настоящее условие и будущее следствие"],"notes":["Unless обычно означает if ... not: We will leave unless it rains — уйдём, если не пойдёт дождь.","В реальном будущем после unless обычно используется настоящее время, а не will."],"lexicon":[{"en":"forecast","ru":"прогноз"},{"en":"cancel","ru":"отменять"},{"en":"shelter","ru":"укрытие"},{"en":"equipment","ru":"снаряжение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":10,"prerequisites":["e14d541f-1b76-58c2-b750-789cc15178f9"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"5ebcf706-6786-5ede-956f-069abdd41682","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Прошлое решение и нынешний результат","position":1,"description":"Прошлое решение и нынешний результат: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Соединять прошлое условие с нынешним результатом","Отличать воображаемое следствие от подтверждённого факта"],"notes":["Смешанное условие может связывать несостоявшееся прошлое с нынешним результатом: If I had saved the file, I would have it now.","Had + причастие относится к прошлому условию, would + инфинитив — к гипотетическому настоящему."],"lexicon":[{"en":"backup","ru":"резервная копия"},{"en":"recover","ru":"восстановить"},{"en":"consequence","ru":"последствие"},{"en":"currently","ru":"в настоящее время"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["cce4a02c-5a44-5170-8f1e-0327811bc161"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"59dc13df-e083-5bc6-a786-0ddc9d60a8c7","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Сожаление о завершённом событии","position":2,"description":"Сожаление о завершённом событии: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Выражать сожаление о прошлом через wish + Past Perfect","Отличать фактическую ошибку от желаемого прошлого"],"notes":["Wish + Past Perfect выражает сожаление о прошлом: I wish I had checked the date.","Wish + Past Simple обычно относится к нереальному настоящему; время выбирается по смыслу, а не по внешнему виду прошедшей формы."],"lexicon":[{"en":"regret","ru":"сожаление"},{"en":"deadline","ru":"крайний срок"},{"en":"overlook","ru":"упустить из виду"},{"en":"accurate","ru":"точный"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["5ebcf706-6786-5ede-956f-069abdd41682"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"311c6dc5-d463-59cf-a03d-32a78af0d2ce","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Что будет закончено к сроку","position":3,"description":"Что будет закончено к сроку: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Обозначать завершение к будущему сроку через will have done","Различать контрольную точку и достаточное условие запуска"],"notes":["Future Perfect: will have + причастие обозначает завершение к будущему моменту.","By Friday означает «к пятнице», а on Friday — «в пятницу»; различие важно для сроков."],"lexicon":[{"en":"milestone","ru":"контрольная точка"},{"en":"complete","ru":"завершить"},{"en":"remaining","ru":"оставшийся"},{"en":"schedule","ru":"график"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["59dc13df-e083-5bc6-a786-0ddc9d60a8c7"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"f80cc913-eb26-5bee-a633-7d5095d1ba83","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Когда работу выполняет специалист","position":4,"description":"Когда работу выполняет специалист: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Описывать услуги через have something done","Отличать исполнителя работы от заказчика услуги"],"notes":["Have something done означает организовать выполнение работы другим человеком: I had my laptop repaired.","Время выражается глаголом have, а после объекта стоит причастие: have / had / will have it checked."],"lexicon":[{"en":"technician","ru":"техник"},{"en":"repair","ru":"ремонтировать"},{"en":"inspection","ru":"осмотр"},{"en":"warranty","ru":"гарантия"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["311c6dc5-d463-59cf-a03d-32a78af0d2ce"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"a01adf6c-e625-5e64-a761-e399fb828146","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Как сообщают о неподтверждённых фактах","position":5,"description":"Как сообщают о неподтверждённых фактах: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Передавать сообщения через is said to have done","Сохранять различие между сообщением и подтверждённым фактом"],"notes":["It is reported that ... приписывает сообщение источнику, а не делает говорящего очевидцем.","Is said to have done указывает на действие раньше нынешнего сообщения; is said to do обычно передаёт настоящее или обычное действие."],"lexicon":[{"en":"reportedly","ru":"по сообщениям"},{"en":"source","ru":"источник"},{"en":"verify","ru":"проверять достоверность"},{"en":"estimate","ru":"оценка"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["f80cc913-eb26-5bee-a633-7d5095d1ba83"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"766417de-547f-5fa7-9a5b-9d6e88e9546b","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Сокращаем описание последовательности","position":6,"description":"Сокращаем описание последовательности: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Выражать предшествующее действие через having done","Соотносить исполнитель начального оборота с подлежащим"],"notes":["Having + причастие может показать завершённое действие перед основным: Having checked the figures, she sent the report.","Подразумеваемый исполнитель начального оборота должен совпадать с подлежащим основной части."],"lexicon":[{"en":"revise","ru":"пересматривать"},{"en":"submit","ru":"подавать"},{"en":"figures","ru":"числовые данные"},{"en":"approval","ru":"одобрение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["a01adf6c-e625-5e64-a761-e399fb828146"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"d7a67fe3-c1fb-5427-adb5-4f98d2fc51d3","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Выделяем важную часть сообщения","position":7,"description":"Выделяем важную часть сообщения: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Выделять причину или объект через it was ... that","Отделять возражение к срокам от возражения к самой идее"],"notes":["It was X that ... выделяет конкретный элемент: It was the timing that worried us.","What ... was ... выделяет содержание или результат: What we needed was a clear explanation."],"lexicon":[{"en":"emphasis","ru":"акцент"},{"en":"timing","ru":"выбор времени"},{"en":"objection","ru":"возражение"},{"en":"clarification","ru":"уточнение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["766417de-547f-5fa7-9a5b-9d6e88e9546b"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"973dc33e-9998-54d3-b74e-467a88176fbc","unit_id":"b5e2949e-527f-5851-9a1d-807192dd62ce","title":"Уступка с despite и although","position":8,"description":"Уступка с despite и although: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"B2","objectives":["Выбирать despite + имя/-ing и although + часть","Сохранять положительные и отрицательные стороны оценки"],"notes":["Despite сочетается с существительным или -ing: despite the rain; although вводит часть с подлежащим и сказуемым.","Despite the fact that позволяет ввести полноценную часть; after despite не добавляется of."],"lexicon":[{"en":"setback","ru":"неудача, препятствие"},{"en":"attendance","ru":"посещаемость"},{"en":"nevertheless","ru":"тем не менее"},{"en":"postpone","ru":"откладывать"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":12,"prerequisites":["d7a67fe3-c1fb-5427-adb5-4f98d2fc51d3"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"e63a36c0-a88d-5258-bec4-8c6ebd192880","unit_id":"2bce4487-19ff-5491-9422-a6d52c1fd7fa","title":"Условие без if в формальном письме","position":1,"description":"Условие без if в формальном письме: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"C1","objectives":["Преобразовывать if-условия с помощью had и should","Сохранять степень уверенности при формальном перефразировании"],"notes":["Had + подлежащее + причастие может заменить if + Past Perfect: Had we known ... = If we had known ...","Should + подлежащее + инфинитив вводит возможное будущее условие в формальном регистре: Should you need assistance ..."],"lexicon":[{"en":"contingency","ru":"непредвиденная ситуация"},{"en":"disclose","ru":"раскрывать информацию"},{"en":"assistance","ru":"помощь"},{"en":"prior","ru":"предшествующий"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":15,"prerequisites":["836a38b3-271d-51e7-b452-17062cee67d4"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"9c2f10a0-899f-5898-80a1-6da9b84b612d","unit_id":"2bce4487-19ff-5491-9422-a6d52c1fd7fa","title":"Контраст и порядок аргументов","position":2,"description":"Контраст и порядок аргументов: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"C1","objectives":["Выносить дополнение для смыслового контраста","Отличать ограничение по срокам от отказа от предложения"],"notes":["Вынос дополнения в начало может создать контраст: The cost we could absorb; the delay we could not.","Такой вынос не требует автоматической инверсии; отрицательная инверсия — отдельная конструкция."],"lexicon":[{"en":"absorb a cost","ru":"взять расходы на себя"},{"en":"constraint","ru":"ограничение"},{"en":"trade-off","ru":"компромисс между требованиями"},{"en":"feasibility","ru":"осуществимость"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":15,"prerequisites":["e63a36c0-a88d-5258-bec4-8c6ebd192880"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"eb6a9b2e-6fff-580b-9c29-a228936552b2","unit_id":"2bce4487-19ff-5491-9422-a6d52c1fd7fa","title":"К чему относятся this и which","position":3,"description":"К чему относятся this и which: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"C1","objectives":["Находить отсылку this/which к предшествующему событию","Выявлять неподтверждённую причинную связь в пересказе"],"notes":["This может отсылать к целому предшествующему утверждению, а не только к ближайшему существительному.","Which после запятой может комментировать целую часть: The trial ended early, which limited the evidence."],"lexicon":[{"en":"referent","ru":"объект отсылки"},{"en":"cohesion","ru":"связность"},{"en":"attrition","ru":"выбывание участников"},{"en":"limitation","ru":"ограничение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":15,"prerequisites":["9c2f10a0-899f-5898-80a1-6da9b84b612d"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks; no independent teacher review","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"3639bcf8-8237-50c3-97c7-f1d075ff3938","unit_id":"2bce4487-19ff-5491-9422-a6d52c1fd7fa","title":"Точная профессиональная критика","position":4,"description":"Точная профессиональная критика: разбираем конструкцию и её смысл на примерах, в диалоге и авторском тексте без аудирования.","level":"C1","objectives":["Направлять критику на проверяемое утверждение","Отличать поддержку пилота от одобрения полного внедрения"],"notes":["Критика может относиться к утверждению, а не к личности: The estimate requires justification вместо You are careless.","Would benefit from предлагает улучшение, не объявляя полную непригодность; существенное требование безопасности нельзя скрывать вежливым смягчением."],"lexicon":[{"en":"substantiated","ru":"подкреплённый доказательствами"},{"en":"feasible","ru":"осуществимый"},{"en":"constructive","ru":"конструктивный"},{"en":"reservation","ru":"оговорка, сомнение"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":15,"prerequisi